      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP made precision measurements of the cosmic microwave background that sharply constrained the universe's age, contents, and early history. This is a major empirical achievement in cosmology.",
        "attribution": "The proposed names capture leading contributions to the mission, instrument, and cosmological interpretation, while recognizing that the result was produced by a broad team.",
        "maturity": "The measurements have been extensively checked and their cosmological implications tested against later observations.",
        "uncertainties": [
          "The distinction between WMAP's advances and earlier CMB discoveries already recognized by the Nobel Prize deserves particular scrutiny."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Enrico Costa",
        "Filippo Frontera",
        "Shrinivas R. Kulkarni"
      ],
      "assessment": {
        "nobel_worthiness": "Identifying gamma-ray burst afterglows and establishing their cosmological distances transformed brief gamma-ray flashes into tools for studying extreme explosions across the universe.",
        "attribution": "The named researchers made consequential observational contributions to the afterglow discovery and the establishment of the cosmological interpretation; precise credit across instruments and teams merits review.",
        "maturity": "The cosmological origin of the bursts is firmly established, and afterglow observations have since become a mature field.",
        "uncertainties": [
          "The discovery chain involved several observatories and rapid follow-up teams, making individual credit difficult to delimit."
        ]
      }
    },
    {
